        return None
    key_pat = re.compile('(?<![A-Za-z0-9_])(?:' + '|'.join(keys) + ')"\\s*:')
    close_pat = re.compile('"\\s*[}\\]]\\s*(?:,|[}\\]]|$)')
    flat = ' '.join(str(context or '').split())
    for pat in (key_pat, close_pat):
        for m in pat.finditer(s):
            frag = ' '.join(m.group(0).split())
            if frag and frag in flat:
                continue
            return m.group(0)
    return None
